l, detail = total + extra, detail .. \" +crit \" .. extra\n        end\n        msg = msg .. total .. (a.hit and \" dmg \" or \" \") .. detail .. \"  \"\n    end\n    msg = msg .. \"(\" .. a.note .. \")\"\n    if a.hit and self.RPGFigurine then self.RPGFigurine.attack() end\n    broadcastToColor(msg, \"Black\", { 1, 0.8, 0.4 })\n    if player.color ~= \"Black\" then broadcastToColor(msg, player.color, { 1, 0.8, 0.4 }) end\nend\n",["LuaScriptState"]="{\"name\": \"Leashed thrall\", \"hp\": 8, \"max\": 8, \"def\": 11, \"down\": false, \"attacks\": [{\"name\": \"Rusty knife\", \"hit\": 3, \"dmg\": \"1d6\", \"note\": \"melee\"}], \"ui\": 230, \"ctl\": \"901d00\"}",["XmlUI"]="",["Tags"]={"scene"},["GUID"]="36bda5",["grid"]={["x"]=4,["z"]=-1,["k"]="fig",["s"]={1,1,1}}},{["Name"]="rpg_GHOUL",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=270.0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="Leashed thrall",["Description"]="",["GMNotes"]="Captured looter on a chain. Cutting the leash (Agility DC 12) and the thrall runs off.",["ColorDiffuse"]={["r"]=0.05,["g"]=0.05,["b"]=0.05},["Locked"]=false,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=true,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="-- NPC: healthbar everyone sees; HP, damage box and attack buttons only the GM (Black seat / host) sees.\n-- Damage box: \"12\" or \"+12\" deals damage, \"-5\" heals. Attack buttons roll and whisper the result to the GM.\n-- ponytail: UI placement is eyeballed; if the bar sits oddly on a model, tweak UI_HEIGHT in build.py or UI_ROT here.\nUI_SCALE = \"0.4 0.4 0.4\"\n-- the bar stands upright and faces where the figure faces (its +z): Euler (90, -90, 90) in the object-UI frame\n-- (x = object x, z = object down). \"0 0 180\" lay flat; \"(yaw - 90) -90 90\" stood up facing south.\nUI_ROT = \"90 -90 90\"\nlocal GM = \"Black\"   -- not \"Host\": the host sitting in a player seat would still see GM-onl