se,["Hands"]=false,["LuaScript"]="",["LuaScriptState"]="",["XmlUI"]="",["Tags"]={"scene"},["grid"]={["x"]=5.6,["z"]=4.6,["k"]="model",["s"]={1,1,1},["lift"]=0},["GUID"]="9b7b69",["CustomMesh"]={["MeshURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/bed.obj",["DiffuseURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/bed.jpg",["NormalURL"]="",["ColliderURL"]="",["Convex"]=false,["MaterialIndex"]=1,["TypeIndex"]=0,["CastShadows"]=true}},{["Name"]="Custom_Model",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=110,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="",["Description"]="",["GMNotes"]="",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=true,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=false,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="",["LuaScriptState"]="",["XmlUI"]="",["Tags"]={"scene"},["grid"]={["x"]=6.4,["z"]=4.0,["k"]="model",["s"]={1,1,1},["lift"]=0},["GUID"]="a5c7bf",["CustomMesh"]={["MeshURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/bed.obj",["DiffuseURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/bed.jpg",["NormalURL"]="",["ColliderURL"]="",["Convex"]=false,["MaterialIndex"]=1,["TypeIndex"]=0,["CastShadows"]=true}},{["Name"]="Custom_Model",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=70,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="",["Description"]="",["GMNotes"]="",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=false,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=false,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="",["LuaScriptState"]="",["XmlUI"]="",["Tags"]={"scene"},["grid"]={["x"]=6.6,["z"]=4.9,["k"]="model",["s"]={1,1,1},["lift"]=0.3},["GUID"]="a8d551",["CustomMesh"]={["MeshURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/sack.obj",["DiffuseURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/sack.jpg",["NormalURL"]="",["ColliderURL"]="",["Convex"]=true,["MaterialIndex"]=1,["TypeIndex"]=0,["CastShadows"]=true}},{["Name"]="Custom_Model",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=140,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="",["Description"]="",["GMNotes"]="",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=true,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=false,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="",["LuaScriptState"]="",["XmlUI"]="",["Tags"]={"scene"},["grid"]={["x"]=5.4,["z"]=3.4,["k"]="model",["s"]={0.5,0.5,0.5},["lift"]=0},["GUID"]="92e89d",["CustomMesh"]={["MeshURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/rubble.obj",["DiffuseURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/rubble.jpg",["NormalURL"]="",["ColliderURL"]="",["Convex"]=false,["MaterialIndex"]=1,["TypeIndex"]=0,["CastShadows"]=true}},{["Name"]="rpg_RAT",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=270.0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="Giant rat",["Description"]="",["GMNotes"]="Only attacks if the bell trap rings or it's cornered.",["ColorDiffuse"]={["r"]=0.05,["g"]=0.05,["b"]=0.05},["Locked"]=false,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=true,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="-- NPC: healthbar everyone sees; HP, damage box and attack buttons only the GM (Black seat / host) sees.\n-- Damage box: \"12\" or \"+12\" deals damage, \"-5\" heals. Attack buttons roll and whisper the result to the GM.\n-- ponytail: UI placement is eyeballed; if the bar sits oddly on a model, tweak UI_HEIGHT in build.py or UI_ROT here.\nUI_SCALE = \"0.4 0.4 0.4\"\n-- the bar stands upright and faces where the figure faces (its +z): Euler (90, -90, 90) in the object-UI frame\n-- (x = object x, z = object down). \"0 0 180\" lay flat; \"(yaw - 90) -90 90\" stood up facing south.\nUI_ROT = \"90 -90 90\"\nlocal GM = \"Black\"   -- not \"Host\": the host sitting in a player seat would still see GM-only UI\nlocal S\n-- the panel is placed by its centre; put the health bar (its bottom row) at S.ui above the base, per model (build.py)\nfunction uiPos() return string.format(\"0 0 %d\", -math.floor((S.ui or 430) + (60 + 44 * (#S.attacks + (S.hidden and 1 or 0))) * 0.4 / 2)) end\n\nfunction onLoad(saved)\n    S = JSON.decode(saved)\n    draw()\nend\n\nfunction onSave() return JSON.encode(S) end\n\nfunction draw()\n    -- top to bottom: attack buttons and HP/damage (GM only), then the health bar right above the figure\n    local x = { string.format(\n        '<Panel position=\"%s\" rotation=\"%s\" scale=\"%s\" width=\"300\" height=\"%d\"><VerticalLayout spacing=\"4\" childForceExpandHeight=\"false\">',\n        uiPos(), UI_ROT, UI_SCALE, 60 + 44 * (#S.attacks + (S.hidden and 1 or 0))) }\n    if S.hidden then   -- GM-only: show this NPC to the players now\n        x[#x + 1] = '<Button id=\"reveal\" onClick=\"revealMe\" visibility=\"' .. GM ..\n            '\" preferredHeight=\"40\" fontSize=\"16\" colors=\"#5a4a10|#7a6418|#3a2a08|#5a4a10\" textColor=\"#f0d9a0\">Reveal</Button>'\n    end\n    for i, a in ipairs(S.attacks) do\n        x[#x + 1] = '<Button id=\"a' .. i .. '\" onClick=\"attack\" visibility=\"' .. GM ..\n            '\" preferredHeight=\"40\" fontSize=\"16\" colors=\"#3a2a1a|#5a4028|#2a1a0a|#3a2a1a\" textColor=\"#f0d9a0\">' ..\n            a.name .. '</Button>'\n    end\n    x[#x + 1] = '<HorizontalLayout visibility=\"' .. GM .. '\" preferredHeight=\"34\" spacing=\"4\">' ..\n        '<Text id=\"hp\" fontSize=\"18\" color=\"#ffffff\" outline=\"#000000\">' .. hpText() .. '</Text>' ..\n        '<InputField id=\"dmg\" placeholder=\"dmg\" onEndEdit=\"applyDamage\" fontSize=\"18\"/></HorizontalLayout>'\n    x[#x + 1] = '<ProgressBar id=\"bar\" preferredHeight=\"22\"' .. (S.hidden and ' visibility=\"' .. GM .. '\"' or '') ..\n        ' percentage=\"' .. pct() ..\n        '\" fillImageColor=\"#b8322a\" color=\"#000000cc\" showPercentageText=\"false\"/>'\n    x[#x + 1] = '</VerticalLayout></Panel>'\n    self.UI.setXml(table.concat(x))\nend\n\nfunction revealMe(player)\n    if player.color == \"Black\" then getObjectFromGUID(S.ctl).call(\"revealGuid\", { guid = self.getGUID() }) end\nend\n\n-- called by the controller: while hidden from players, the health bar is GM-only too\nfunction setHidden(p)\n    S.hidden = p.hidden\n    draw()\nend\n\nfunction pct() return math.floor(100 * S.hp / S.max) end\nfunction hpText() return S.hp .. \"/\" .. S.max .. \"  Def \" .. S.def end\n\nfunction applyDamage(player, value)\n    -- MoonSharp's tonumber(s, 10) throws on \"-5\"/\"\", so pattern-check first and call it without a base\n    local num = (value or \"\"):match(\"^%s*%+?(%-?%d+)%s*$\")\n    local n = num and tonumber(num)\n    if not n or n == 0 then return end\n    S.hp = math.max(0, math.min(S.max, S.hp - n))\n    self.UI.setAttribute(\"bar\", \"percentage\", pct())\n    self.UI.setAttribute(\"hp\", \"text\", hpText())\n    self.UI.setAttribute(\"dmg\", \"text\", \"\")\n    -- die() toggles the lying pose; S.down tracks it so figures that start lying (the princess) stand when healed\n    local down = S.hp == 0\n    if down ~= (S.down or false) then\n        S.down = down\n        if self.RPGFigurine then self.RPGFigurine.die() end\n        broadcastToAll(S.name .. (down and \" falls!\" or \" gets back up!\"), { 0.9, 0.4, 0.3 })\n    end\nend\n\n-- \"2d8+4\" -> total, \"5,3 +4\"\nfunction roll(expr)\n    local n, d, m = expr:match(\"^(%d+)d(%d+)([%+%-]?%d*)$\")\n    local total, parts = 0, {}\n    for _ = 1, tonumber(n) do\n        local r = math.random(tonumber(d))\n        total = total + r\n        parts[#parts + 1] = r\n    end\n    m = tonumber(m) or 0\n    return total + m, \"[\" .. table.concat(parts, \",\") .. \"]\" .. (m ~= 0 and string.format(\"%+d\", m) or \"\")\nend\n\nfunction attack(player, _, id)\n    local a = S.attacks[tonumber(id:sub(2))]\n    local msg = S.name .. \" - \" .. a.name .. \": \"\n    local crit = false\n    if a.hit then\n        local d20 = math.random(20)\n        crit = d20 == 20\n        msg = msg .. (d20 + a.hit) .. \" to hit (d20 \" .. d20 .. (crit and \" CRIT\" or d20 == 1 and \" FUMBLE\" or \"\") .. \")  \"\n    end\n    if a.dmg then\n        local total, detail = roll(a.dmg)\n        if crit then\n            local extra = roll(a.dmg:gsub(\"[%+%-]%d+$\", \"\"))\n            total, detail = total + extra, detail .. \" +crit \" .. extra\n        end\n        msg = msg .. total .. (a.hit and \" dmg \" or \" \") .. detail .. \"  \"\n    end\n    msg = msg .. \"(\" .. a.note .. \")\"\n    if a.hit and self.RPGFigurine then self.RPGFigurine.attack() end\n    broadcastToColor(msg, \"Black\", { 1, 0.8, 0.4 })\n    if player.color ~= \"Black\" then broadcastToColor(msg, player.color, { 1, 0.8, 0.4 }) end\nend\n",["LuaScriptState"]="{\"name\": \"Giant rat\", \"hp\": 6, \"max\": 6, \"def\": 12, \"down\": false, \"attacks\": [{\"name\": \"Bite\", \"hit\": 4, \"dmg\": \"1d6\", \"note\": \"melee\"}], \"ui\": 130, \"ctl\": \"901d00\"}",["XmlUI"]="",["Tags"]={"scene"},["GUID"]="d162d8",["grid"]={["x"]=5.6,["z"]=3.6,["k"]="fig",["s"]={1,1,1}}},{["Name"]="rpg_RAT",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=270.0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="Giant rat",["Description"]="",["GMNotes"]="Only attacks if the bell trap rings or it's cornered.",["ColorDiffuse"]={["r"]=0.05,["g"]=0.05,["b"]=0.05},["Locked"]=false,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=true,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="-- NPC: healthbar everyone sees; HP, damage box and attack buttons only the GM (Black seat / host) sees.\n-- Damage box: \"12\" or \"+12\" deals damage, \"-5\" heals. Attack buttons roll and whisper the result to the GM.\n-- ponytail: UI placement is eyeballed; if the bar sits oddly on a model, tweak UI_HEIGHT in build.py or UI_ROT here.\nUI_SCALE = \"0.4 0.4 0.4\"\n-- the bar stands upright and faces where the figure faces (its +z): Euler (90, -90, 90) in the object-UI frame\n-- (x = object x, z = object down). \"0 0 180\" lay flat; \"(yaw - 90) -90 90\" stood up facing south.\nUI_ROT = \"90 -90 90\"\nlocal GM = \"Black\"   -- not \"Host\": the host sitting in a player seat would still see GM-only UI\nlocal S\n-- the panel is placed by its centre; put the health bar (its bottom row) at S.ui above the base, per model (build.py)\nfunction uiPos() return string.format(\"0 0 %d\", -math.floor((S.ui or 430) + (60 + 44 * (#S.attacks + (S.hidden and 1 or 0))) * 0.4 / 2)) end\n\nfunction onLoad(saved)\n    S = JSON.decode(saved)\n    draw()\nend\n\nfunction onSave() return JSON.encode(S) end\n\nfunction draw()\n    -- top to bottom: attack buttons and HP/damage (GM only), then the health bar right above the figure\n    local x = { string.format(\n        '<Panel position=\"%s\" rotation=\"%s\" scale=\"%s\" width=\"300\" height=\"%d\"><VerticalLayout spacing=\"4\" childForceExpandHeight=\"false\">',\n        uiPos(), UI_ROT, UI_SCALE, 60 + 44 * (#S.attacks + (S.hidden and 1 or 0))) }\n    if S.hidden then   -- GM-only: show this NPC to the players now\n        x[#x + 1] = '<Button id=\"reveal\" onClick=\"revealMe\" visibility=\"' .. GM ..\n            '\" preferredHeight=\"40\" fontSize=\"16\" colors=\"#5a4a10|#7a6418|#3a2a08|#5a4a10\" textColor=\"#f0d9a0\">Reveal</Button>'\n    end\n    for i, a in ipairs(S.attacks) do\n        x[#x + 1] = '<Button id=\"a' .. i .. '\" onClick=\"attack\" visibility=\"' .. GM ..\n            '\" preferredHeight=\"40\" fontSize=\"16\" colors=\"#3a2a1a|#5a4028|#2a1a0a|#3a2a1a\" textColor=\"#f0d9a0\">' ..\n            a.name .. '</Button>'\n    end\n    x[#x + 1] = '<HorizontalLayout visibility=\"' .. GM .. '\" preferredHeight=\"34\" spacing=\"4\">' ..\n        '<Text id=\"hp\" fontSize=\"18\" color=\"#ffffff\" outline=\"#000000\">' .. hpText() .. '</Text>' ..\n        '<InputField id=\"dmg\" placeholder=\"dmg\" onEndEdit=\"applyDamage\" fontSize=\"18\"/></HorizontalLayout>'\n    x[#x + 1] = '<ProgressBar id=\"bar\" preferredHeight=\"22\"' .. (S.hidden and ' visibility=\"' .. GM .. '\"' or '') ..\n        ' percentage=\"' .. pct() ..\n        '\" fillImageColor=\"#b8322a\" color=\"#000000cc\" showPercentageText=\"false\"/>'\n    x[#x + 1] = '</VerticalLayout></Panel>'\n    self.UI.setXml(table.concat(x))\nend\n\nfunction revealMe(player)\n    if player.color == \"Black\" then getObjectFromGUID(S.ctl).call(\"revealGuid\", { guid = self.getGUID() }) end\nend\n\n-- called by the controller: while hidden from players, the health bar is GM-only too\nfunction setHidden(p)\n    S.hidden = p.hidden\n    draw()\nend\n\nfunction pct() return math.floor(100 * S.hp / S.max) end\nfunction hpText() return S.hp .. \"/\" .. S.max .. \"  Def \" .. S.def end\n\nfunction applyDamage(player, value)\n    -- MoonSharp's tonumber(s, 10) throws on \"-5\"/\"\", so pattern-check first and call it without a base\n    local num = (value or \"\"):match(\"^%s*%+?(%-?%d+)%s*$\")\n    local n = num and tonumber(num)\n    if not n or n == 0 then return end\n    S.hp = math.max(0, math.min(S.max, S.hp - n))\n    self.UI.setAttribute(\"bar\", \"percentage\", pct())\n    self.UI.setAttribute(\"hp\", \"text\", hpText())\n    self.UI.setAttribute(\"dmg\", \"text\", \"\")\n    -- die() toggles the lying pose; S.down tracks it so figures that start lying (the princess) stand when healed\n    local down = S.hp == 0\n    if down ~= (S.down or false) then\n        S.down = down\n        if self.RPGFigurine then self.RPGFigurine.die() end\n        broadcastToAll(S.name .. (down and \" falls!\" or \" gets back up!\"), { 0.9, 0.4, 0.3 })\n    end\nend\n\n-- \"2d8+4\" -> total, \"5,3 +4\"\nfunction roll(expr)\n    local n, d, m = expr:match(\"^(%d+)d(%d+)([%+%-]?%d*)$\")\n    local total, parts = 0, {}\n    for _ = 1, tonumber(n) do\n        local r = math.random(tonumber(d))\n        total = total + r\n        parts[#parts + 1] = r\n    end\n    m = tonumber(m) or 0\n    return total + m, \"[\" .. table.concat(parts, \",\") .. \"]\" .. (m ~= 0 and string.format(\"%+d\", m) or \"\")\nend\n\nfunction attack(player, _, id)\n    local a = S.attacks[tonumber(id:sub(2))]\n    local msg = S.name .. \" - \" .. a.name .. \": \"\n    local crit = false\n    if a.hit then\n        local d20 = math.random(20)\n        crit = d20 == 20\n        msg = msg .. (d20 + a.hit) .. \" to hit (d20 \" .. d20 .. (crit and \" CRIT\" or d20 == 1 and \" FUMBLE\" or \"\") .. \")  \"\n    end\n    if a.dmg then\n        local total, detail = roll(a.dmg)\n        if crit then\n            local extra = roll(a.dmg:gsub(\"[%+%-]%d+$\", \"\"))\n            total, detail = total + extra, detail .. \" +crit \" .. extra\n        end\n        msg = msg .. total .. (a.hit and \" dmg \" or \" \") .. detail .. \"  \"\n    end\n    msg = msg .. \"(\" .. a.note .. \")\"\n    if a.hit and self.RPGFigurine then self.RPGFigurine.attack() end\n    broadcastToColor(msg, \"Black\", { 1, 0.8, 0.4 })\n    if player.color ~= \"Black\" then broadcastToColor(msg, player.color, { 1, 0.8, 0.4 }) end\nend\n",["LuaScriptState"]="{\"name\": \"Giant rat\", \"hp\": 6, \"max\": 6, \"def\": 12, \"down\": false, \"attacks\": [{\"name\": \"Bite\", \"hit\": 4, \"dmg\": \"1d6\", \"note\": \"melee\"}], \"ui\": 130, \"ctl\": \"901d00\"}",["XmlUI"]=""