sY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="",["Description"]="",["GMNotes"]="",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=true,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=false,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="",["LuaScriptState"]="",["XmlUI"]="",["Tags"]={"scene"},["grid"]={["x"]=6.8,["z"]=-6.2,["k"]="model",["s"]={1,1,1},["lift"]=0},["GUID"]="689556",["CustomMesh"]={["MeshURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/oak.obj",["DiffuseURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/oak.jpg",["NormalURL"]="",["ColliderURL"]="",["Convex"]=false,["MaterialIndex"]=1,["TypeIndex"]=0,["CastShadows"]=true}},{["Name"]="Custom_Model",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="",["Description"]="",["GMNotes"]="",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=true,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=false,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="",["LuaScriptState"]="",["XmlUI"]="",["Tags"]={"scene"},["grid"]={["x"]=-6.8,["z"]=-6.6,["k"]="model",["s"]={1,1,1},["lift"]=0},["GUID"]="3da1b3",["CustomMesh"]={["MeshURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/pine_b.obj",["DiffuseURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/f0681cb343531dac733815f890725bc438f0aa84/props/pine_b.jpg",["NormalURL"]="",["ColliderURL"]="",["Convex"]=false,["MaterialIndex"]=1,["TypeIndex"]=0,["CastShadows"]=true}},{["Name"]="Custom_Model",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=40,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},[